import { existsSync, readdirSync, readFileSync } from "node:fs";
import { expect, test } from "@playwright/test";
import { parseManifest, type ToolkitManifest } from "../../src/core/manifest.ts";

// The toolkit is the repository root, one folder above page/. The manifest is generated by `npm run build`.
const ROOT = "..";

function load(): ToolkitManifest {
  const parsed = parseManifest(JSON.parse(readFileSync("src/generated/toolkit.manifest.json", "utf8")));
  if (!parsed.ok) throw new Error(parsed.error);
  return parsed.value;
}

test("the manifest parses and every item has a short plain-English line", () => {
  const manifest = load();
  expect(manifest.items.length).toBeGreaterThan(80);
  for (const item of manifest.items) {
    expect(item.oneLiner.length, item.id).toBeGreaterThan(10);
    expect(item.oneLiner.length, item.id).toBeLessThanOrEqual(100);
    expect(item.oneLiner.split(/\s+/).length, item.id).toBeLessThanOrEqual(15);
  }
});

test("the manifest rejects broken data at the boundary", () => {
  expect(parseManifest({ schema: 2 }).ok).toBe(false);
  expect(parseManifest({ schema: 1, toolkit: { sha: "x", headDate: "y", repoUrl: null }, items: [{ id: "Bad Id" }] }).ok).toBe(false);
});

test("the manifest has one item for each thing in the toolkit", () => {
  const manifest = load();
  const count = (kind: string) => manifest.items.filter((i) => i.kind === kind).length;
  const skillDirs = readdirSync(`${ROOT}/skills`).filter((d) => existsSync(`${ROOT}/skills/${d}/SKILL.md`));
  const kitDirs = readdirSync(`${ROOT}/kits`).filter((d) => existsSync(`${ROOT}/kits/${d}/README.md`));
  expect(count("skill")).toBe(skillDirs.length);
  expect(count("kit")).toBe(kitDirs.length);
  expect(count("animation")).toBe(1);
  expect(count("installer")).toBe(readdirSync(`${ROOT}/install`).length);
  expect(manifest.items.filter((i) => i.kind === "motion" && i.motion.part === "move")).toHaveLength(11);
  expect(manifest.items.filter((i) => i.kind === "motion" && i.motion.part === "transition")).toHaveLength(11);
});
